package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim of a person on a sheet. Mutable so an Apply step can change it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;

    private String editedBy;
    private Integer settleBatch;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate roundOn;
    private LocalDate dueFrom;
    private int terms;
    private LocalDate dueBy;
    private LocalDate deferredUntil;
    private int proofs;
    private String splitFrom;
    private boolean lateEntry;
    private LocalDate remindedOn;
    private String ref;
    private String tags;
    private String voidReason;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy,
            boolean stated, BigDecimal statedDue, String corrects) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
        this.roundOn = date;
    }

    /** The date the claim's due-by counts from: its date when it was added, kept when the date later changes. */
    public LocalDate getDueFrom() {
        return dueFrom;
    }

    public void setDueFrom(LocalDate dueFrom) {
        this.dueFrom = dueFrom;
    }

    /** The terms the claim was fixed with when it was added: those in force on its date for its person, in business days. */
    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    /**
     * The date the claim is due by: the terms-th business day after its due-from date (skipping Saturdays, Sundays and
     * the sheet's holidays as they stand now), worked out whenever the claim is read.
     */
    public LocalDate getDueBy() {
        return dueBy;
    }

    public void setDueBy(LocalDate dueBy) {
        this.dueBy = dueBy;
    }

    /** The date the claim was last deferred until; null when it was never deferred. */
    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    /** The number of the claim this one was split off; null when it was not split off one. */
    public String getSplitFrom() {
        return splitFrom;
    }

    public void setSplitFrom(String splitFrom) {
        this.splitFrom = splitFrom;
    }

    /** Whether the claim was added while the period containing its date was soft-closed. */
    public boolean isLateEntry() {
        return lateEntry;
    }

    public void setLateEntry(boolean lateEntry) {
        this.lateEntry = lateEntry;
    }

    /** The last sheet-today a reminder was written for the claim; null when never reminded. */
    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

    /** The claim's external reference; null when it has none. */
    public String getRef() {
        return ref;
    }

    public void setRef(String ref) {
        this.ref = ref;
    }

    /** The claim's tags, sorted and joined by commas; null when it has none. */
    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    /** The reason the claim was voided with, from the sheet's list; null when none was given. */
    public String getVoidReason() {
        return voidReason;
    }

    public void setVoidReason(String voidReason) {
        this.voidReason = voidReason;
    }

    /** Keep {@code amount} of the claim, the rest split off: it loses any figure a statement bound it to. */
    public void keep(BigDecimal amount) {
        this.amount = amount;
        this.stated = false;
        this.statedDue = null;
    }

    /** How many proofs the claim carries. */
    public int getProofs() {
        return proofs;
    }

    public void setProofs(int proofs) {
        this.proofs = proofs;
    }

    /** Whether the claim is deferred as of {@code today}: OPEN, and deferred until a date after today. Until then it
     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return status == ClaimStatus.OPEN && deferredUntil != null && today != null && today.isBefore(deferredUntil);
    }

    /** The date the claim's live figures round by: its own, or for a correction the date of the claim it corrects. */
    public LocalDate getRoundOn() {
        return roundOn;
    }

    public void setRoundOn(LocalDate roundOn) {
        this.roundOn = roundOn;
    }

    public long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public long getPersonId() {
        return personId;
    }

    /** Move the claim to another person: it loses any figure a statement bound it to. */
    public void moveTo(long personId) {
        this.personId = personId;
        this.stated = false;
        this.statedDue = null;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        if (corrects == null) {
            this.roundOn = date;
        }
        this.date = date;
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public void setStatus(ClaimStatus status) {
        this.status = status;
    }

    /** The number given when the claim was opened; null for a draft (or a claim voided as a draft); a voided claim keeps its number, never reused. */
    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    /** The due fixed when the claim was settled; null when not settled or settled without a rate. */
    public BigDecimal getSettledDue() {
        return settledDue;
    }

    public void setSettledDue(BigDecimal settledDue) {
        this.settledDue = settledDue;
    }

    /** The signed-in user who opened the claim; null when it was never opened. */
    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    /** The number of the bulk settle batch that settled the claim; null when no batch settled it. */
    public Integer getSettleBatch() {
        return settleBatch;
    }

    public void setSettleBatch(Integer settleBatch) {
        this.settleBatch = settleBatch;
    }

    /** The signed-in user who last edited the claim through its form or amount entry; null when never edited. */
    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    /** Whether the person's last statement bound the claim to a figure. */
    public boolean isStated() {
        return stated;
    }

    /** Whether the last statement's figure is the claim's: it was stated, and is not PENDING (a PENDING claim shows and
     *  totals its live figure; rejected back to OPEN, it is bound again). */
    public boolean isBound() {
        return stated && status != ClaimStatus.PENDING;
    }

    /** The figure the last statement bound the claim to; null when bound without one (n/a) or not bound. */
    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** The number of the SETTLED claim this correction corrects; null for a claim that is not a correction. */
    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    /** Whether the claim is a correction: its amount is below 0.00 (no floor and no late charge apply). */
    public boolean isCorrection() {
        return amount.signum() < 0;
    }

    /**
     * The claim's rate figure: its amount times the rate, rounded to two decimals by the rounding given. The floor is
     * not applied here; it comes last, after the late charge (see LateCharge). Null without a rate.
     */
    public BigDecimal figureAt(BigDecimal rate, java.math.RoundingMode rounding) {
        if (rate == null) {
            return null;
        }
        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** A person on a sheet. Mutable so an Apply step can change it in place. */
public class Person {

    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    private List<GradeFrom> grades = List.of();
    private long version;
    private Statements statements = Statements.NONE;
    private LocalDate retiredFrom;
    private List<HoldSpan> holds = List.of();
    private List<RetirementSpan> retirements = List.of();
    private List<String> patrons = List.of();
    private List<String> aliases = List.of();
    private List<SnapshotLine> snapshots = List.of();
    private Integer terms;
    private String contact;
    private String tags;

    private String origin;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grade in force on the sheet's today. */
    public String getGrade() {
        return grade;
    }

    public void setGrade(String grade) {
        this.grade = grade;
    }

    /** The grades the person was given, each from its from-date (the first from the beginning of time). */
    public List<GradeFrom> getGrades() {
        return grades;
    }

    public void setGrades(List<GradeFrom> grades) {
        this.grades = grades;
    }

    /** The grade in force on the date: the one with the latest from-date on or before it, none counting as the earliest. */
    public String gradeOn(LocalDate on) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && g.from().isAfter(on)) {
                continue;
            }
            if (found == null || (g.from() != null && (found.from() == null || g.from().isAfter(found.from())))) {
                found = g;
            }
        }
        return found == null ? grade : found.grade();
    }

    /** The person's own terms in days; null when they have none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    /** The person's tags, sorted and joined by commas; null when they have none. */
    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    /** The sheet the person was transferred from; null when they were not transferred in. */
    public String getOrigin() {
        return origin;
    }

    public void setOrigin(String origin) {
        this.origin = origin;
    }

    public long getVersion() {
        return version;
    }

    public void setVersion(long version) {
        this.version = version;
    }

    /** The person's statements: how many, and the last one's due-total and date. */
    public Statements getStatements() {
        return statements;
    }

    public void setStatements(Statements statements) {
        this.statements = statements;
    }

    /** The date the person is retired from; null when not retired. Set at all, the person counts as retired. */
    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person's retirement date is reached on the date: from then their OPEN and PENDING claims, unless a
     *  statement binds them, count in no live total, as a hold's would. */
    public boolean retiredOn(LocalDate on) {
        return retiredFrom != null && !on.isBefore(retiredFrom);
    }

    /** The person's past retirements, each from its from-date to the day they were unretired, in the order kept. */
    public List<RetirementSpan> getRetirements() {
        return retirements;
    }

    public void setRetirements(List<RetirementSpan> retirements) {
        this.retirements = retirements;
    }

    /** Whether a claim dated then is refused: after the current retirement's date, or strictly between a past
     *  retirement's from-date and the day it ended. */
    public boolean retiredClaimDate(LocalDate date) {
        return (retiredFrom != null && date.isAfter(retiredFrom))
                || retirements.stream().anyMatch(r -> r.refuses(date));
    }

    /** Whether the person has any hold. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** The person's holds, in the order they were added. */
    public List<HoldSpan> getHolds() {
        return holds;
    }

    public void setHolds(List<HoldSpan> holds) {
        this.holds = holds;
    }

    /** Whether a hold covers the date: the person's OPEN and PENDING claims dated then, unless a statement binds them,
     *  count in no live total. */
    public boolean heldOn(LocalDate on) {
        return holds.stream().anyMatch(h -> h.covers(on));
    }

    /** The names of the person's patrons, sorted. */
    public List<String> getPatrons() {
        return patrons.stream().sorted().toList();
    }

    /** The names of the person's patrons, in the order they were named. */
    public List<String> getPatronsNamed() {
        return patrons;
    }

    /** Sets the names of the person's patrons, in the order they were named. */
    public void setPatrons(List<String> patrons) {
        this.patrons = patrons;
    }

    /**
     * The person's patrons with their shares, sorted by name: 100.00 split equally in the order they were named, each
     * share rounded half to even to two decimals, the remainder (100.00 less the shares added up) to the first named.
     */
    public List<PatronShare> getPatronShares() {
        if (patrons.isEmpty()) {
            return List.of();
        }
        BigDecimal hundred = new BigDecimal("100.00");
        BigDecimal each = hundred.divide(BigDecimal.valueOf(patrons.size()), 2, RoundingMode.HALF_EVEN);
        BigDecimal first = hundred.subtract(each.multiply(BigDecimal.valueOf(patrons.size() - 1)));
        List<PatronShare> shares = new ArrayList<>();
        for (int i = 0; i < patrons.size(); i++) {
            shares.add(new PatronShare(patrons.get(i), i == 0 ? first : each));
        }
        shares.sort(Comparator.comparing(PatronShare::name));
        return shares;
    }

    private boolean clashing;

    /** Whether the person's name or an alias of theirs is used, as a name or alias, on another sheet of their tree. */
    public boolean isClashing() {
        return clashing;
    }

    public void setClashing(boolean clashing) {
        this.clashing = clashing;
    }

    /** The person's aliases, sorted as names are compared. */
    public List<String> getAliases() {
        return aliases;
    }

    public void setAliases(List<String> aliases) {
        this.aliases = aliases;
    }

    /** The person's snapshot lines, oldest first. */
    public List<SnapshotLine> getSnapshots() {
        return snapshots;
    }

    public void setSnapshots(List<SnapshotLine> snapshots) {
        this.snapshots = snapshots;
    }
}

