199	        into.setOpenedBy(openedBy);
200	        into.setSplitFrom(claim.getNumber());
201	        jdbc.update("UPDATE claim SET status = ?, opened_by = ?, split_from = ? WHERE id = ?",
202	                ClaimStatus.OPEN.name(), openedBy, claim.getNumber(), into.getId());
