306	    /**
307	     * Run the work in a transaction of its own (nested, to a savepoint, inside one already open), undoing every change
308	     * it made to the store when it answers false. Answers what the work answered.
309	     */
310	    public boolean keepOnly(BooleanSupplier work) {
311	        TransactionTemplate tx = new TransactionTemplate(new DataSourceTransactionManager(jdbc.getDataSource()));
312	        tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
313	        return Boolean.TRUE.equals(tx.execute(status -> {
314	            boolean keep = work.getAsBoolean();
315	            if (!keep) {
316	                status.setRollbackOnly();
317	            }
318	            return keep;
319	        }));
320	    }
