334	    /**
335	     * Take the next claim number of the sheet's tree within the fiscal year (its name, FY<yyyy>), from 1: one after
336	     * the last given in that year on any of its sheets, kept as this sheet's last. The tree's sheets are locked first
337	     * so two users never get the same one.
338	     */
339	    public int nextFiscalNumber(String sheetId, String fiscalYear) {
340	        List<String> tree = treeOf(sheetId);
341	        String in = String.join(",", java.util.Collections.nCopies(tree.size(), "?"));
342	        jdbc.queryForList("SELECT id FROM sheet WHERE id IN (" + in + ") ORDER BY id FOR UPDATE", String.class, tree.toArray());
343	        List<Object> args = new java.util.ArrayList<>(tree);
344	        args.add(fiscalYear);
345	        Integer last = jdbc.queryForObject("SELECT MAX(last_number) FROM claim_sequence WHERE sheet_id IN (" + in + ")"
346	                + " AND seq_key = ?", Integer.class, args.toArray());
347	        int next = (last == null ? 0 : last) + 1;
348	        if (jdbc.update("UPDATE claim_sequence SET last_number = ? WHERE sheet_id = ? AND seq_key = ?", next, sheetId, fiscalYear) == 0) {
349	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key, last_number) VALUES (?, ?, ?)", sheetId, fiscalYear, next);
350	        }
351	        return next;
352	    }
