354	    /** The sheet's tree: its top ancestor (following parents up), then all the sheets below that, each once. */
355	    private List<String> treeOf(String sheetId) {
356	        java.util.Set<String> up = new java.util.LinkedHashSet<>();
357	        String root = sheetId;
358	        while (up.add(root)) {
359	            String parent = jdbc.query("SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = 'parent'",
360	                    (rs, n) -> rs.getString(1), root).stream().filter(v -> v != null && !v.isBlank()).findFirst().orElse(null);
361	            if (parent == null) {
362	                break;
363	            }
364	            root = parent;
365	        }
366	        java.util.Set<String> tree = new java.util.LinkedHashSet<>(List.of(root));
367	        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(root));
368	        while (!todo.isEmpty()) {
369	            for (String child : jdbc.query("SELECT sheet_id FROM sheet_setting WHERE setting_key = 'parent' AND setting_value = ?",
370	                    (rs, n) -> rs.getString(1), todo.poll())) {
371	                if (tree.add(child)) {
372	                    todo.add(child);
373	                }
374	            }
375	        }
376	        tree.add(sheetId); // under a parent cycle, the walk down may not reach it
377	        return List.copyOf(tree);
378	    }
379	
380	    /** Take the next number of one of the sheet's per-period sequences (a period's id, or X for no period), from 1. */
381	    public int nextNumber(String sheetId, String sequence) {
382	        try {
383	            jdbc.update("INSERT INTO claim_sequence (sheet_id, seq_key) SELECT ?, ? FROM DUAL WHERE NOT EXISTS"
384	                    + " (SELECT 1 FROM claim_sequence WHERE sheet_id = ? AND seq_key = ?)", sheetId, sequence, sheetId, sequence);
385	        } catch (org.springframework.dao.DuplicateKeyException started) {
386	            // another user started it first
387	        }
388	        return jdbc.queryForObject("SELECT last_number FROM FINAL TABLE (UPDATE claim_sequence SET last_number = last_number + 1"
389	                + " WHERE sheet_id = ? AND seq_key = ?)", Integer.class, sheetId, sequence);
390	    }
391	}
