451	    public RollupSnapshot snapshot(String sheetId) {
452	        LocalDate today = sheets.today(sheetId);
453	        List<Rate> sheetRates = rates.chain(sheetId);
454	        List<Claim> sheetClaims = claims.list(sheetId);
455	        LateCharge late = settings.lateCharge(sheetId, today);
456	        BigDecimal cap = late.settings().cap(today);
457	        Map<Long, Figures> figures = new LinkedHashMap<>();
458	        BigDecimal claimedTotal = ZERO;
459	        List<BigDecimal> dues = new ArrayList<>();
460	        List<BigDecimal> overdues = new ArrayList<>();
461	        for (Person p : people.list(sheetId)) {
462	            BigDecimal claimed = ZERO;
463	            BigDecimal due = ZERO;
464	            BigDecimal overdue = ZERO;
465	            boolean kept = false;
466	            for (Claim c : sheetClaims) {
467	                if (c.getPersonId() != p.getId() || !counts(c, p, today)) {
468	                    continue;
469	                }
470	                if (c.getCorrects() == null) {
471	                    claimed = claimed.add(c.getAmount().setScale(2));
472	                }
473	                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
474	                String grade = p.gradeOn(c.getDate());
475	                BigDecimal figure = late.due(c, figure(c, grade, sheetRates, late));
476	                // A figure at a grade other than today's does not hang on today's grade having a rate; nor does one
477	                // dated on or before today, whose rate may have ended since.
478	                kept |= figure != null && (!grade.equals(p.getGrade()) || !c.getDate().isAfter(today));
479	                if (figure != null) {
480	                    due = due.add(figure);
481	                    if (late.overdue(c)) {
482	                        overdue = overdue.add(figure);
483	                    }
484	                }
485	            }
486	            BigDecimal personDue = SettingRepository.capped(
487	                    kept || rateOn(sheetRates, p.getGrade(), today) != null ? due : null, cap);
488	            figures.put(p.getId(), new Figures(p.getName(), claimed, personDue, overdue));
489	            claimedTotal = claimedTotal.add(claimed);
490	            overdues.add(overdue);
491	            if (personDue != null) {
492	                dues.add(personDue);
493	            }
494	        }
495	        return new RollupSnapshot(figures, claimedTotal, trimmed(dues), trimmed(overdues));
496	    }
497	
498	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
499	    static BigDecimal trimmed(List<BigDecimal> figures) {
500	        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
501	        if (figures.size() < 3) {
502	            return sum;
503	        }
504	        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
505	        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
506	        return sum.subtract(max).subtract(min);
507	    }
508	
509	    /**
510	     * The due-total of the claims dated from..to (inclusive) counting by their status at the end of {@code to}, as the
511	     * screen shows a period's: each claim's figure now (with its late charge) added up, a claim without one adding nothing.
512	     */
513	    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
514	        return dueBetweenByPerson(sheetId, from, to).values().stream().reduce(ZERO, BigDecimal::add);
515	    }
516	
517	    /**
518	     * Each person's due-total for the dates from..to (inclusive), by person id, every person on the sheet included
519	     * (0.00 when none of their counting claims is due by a date there: a claim belongs to the period of its due-by): their counting claims' figures (with late charge) added up.
520	     * A claim counts by the status its log records at the end of {@code to} (one added after it does not count); its
521	     * figure is the one it shows now, and a deferred or held claim is left out as the live totals leave it out.
522	     */
523	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
524	        List<Rate> sheetRates = rates.chain(sheetId);
525	        LocalDate today = sheets.today(sheetId);
526	        LateCharge late = settings.lateCharge(sheetId, today);
527	        Map<Long, Person> byId = new LinkedHashMap<>();
528	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
529	        for (Person p : people.list(sheetId)) {
530	            byId.put(p.getId(), p);
531	            totals.put(p.getId(), ZERO);
532	        }
533	        Map<Long, ClaimStatus> asOf = log.statusesAsOf(sheetId, to);
534	        for (Claim c : claims.list(sheetId)) {
535	            Person p = byId.get(c.getPersonId());
536	            ClaimStatus then = asOf.get(c.getId());
537	            if (p == null || then == null || !countsAs(c, then, p, today) || c.getDueBy().isBefore(from)
538	                    || c.getDueBy().isAfter(to)) {
539	                continue;
540	            }
541	            BigDecimal figure = late.due(c, figure(c, p.gradeOn(c.getDate()), sheetRates, late));
542	            if (figure != null) {
543	                totals.merge(p.getId(), figure, BigDecimal::add);
544	            }
545	        }
546	        return totals;
547	    }
548	
549	    /** The claim's due as the screen shows it now: its figure with its late charge on top; null (n/a) without one. */
550	    public BigDecimal dueOf(Claim claim) {
551	        String sheetId = claim.getSheetId();
552	        Person p = people.find(sheetId, claim.getPersonId());
553	        if (p == null) {
554	            return null;
555	        }
556	        LateCharge late = settings.lateCharge(sheetId, sheets.today(sheetId));
557	        return late.due(claim, figure(claim, p.gradeOn(claim.getDate()), rates.chain(sheetId), late));
558	    }
559	
560	    /** Record the figures the change moved, from {@code before} to the sheet's figures now. */
561	    public void record(String sheetId, RollupSnapshot before, ChangedBy by) {
562	        record(sheetId, before, by, false);
563	    }
564	
565	    /** Record the figures the change moved; with {@code totals}, the TOTALS line even when the totals did not move. */
566	    public void record(String sheetId, RollupSnapshot before, ChangedBy by, boolean totals) {
567	        RollupSnapshot after = snapshot(sheetId);
568	        List<String> lines = new ArrayList<>();
569	        String who = " sheet=" + sheetId + " by=" + by.name();
570	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
571	            Figures now = e.getValue();
572	            if (now.movedFrom(before.people().get(e.getKey()))) {
573	                lines.add("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed().toPlainString()
574	                        + " due-total=" + show(now.dueTotal()) + " overdue-total=" + now.overdueTotal().toPlainString());
575	            }
576	        }
577	        if (totals || !after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
578	                || !after.overdueTotal().equals(before.overdueTotal())) {
579	            lines.add("TOTALS" + who + " claimed-total=" + after.claimedTotal().toPlainString() + " due-total="
580	                    + after.dueTotal().toPlainString() + " overdue-total=" + after.overdueTotal().toPlainString());
581	        }
582	        String threshold = settings.find(sheetId, net.officefloor.hq.app.access.Setting.ALERT_THRESHOLD);
583	        if (threshold != null) {
584	            BigDecimal limit = new BigDecimal(threshold);
585	            for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
586	                Figures now = e.getValue();
587	                Figures was = before.people().get(e.getKey());
588	                if (above(now, limit) && !above(was, limit)) {
589	                    lines.add("ALERT" + who + " name=" + now.name() + " due-total=" + now.dueTotal().toPlainString());
590	                }
591	            }
592	        }
593	        lines.forEach(audit::record);
594	    }
595	
596	    /** Whether the person's due-total is above the alert threshold (none, or n/a, is not). */
597	    private static boolean above(Figures figures, BigDecimal limit) {
598	        return figures != null && figures.dueTotal() != null && figures.dueTotal().compareTo(limit) > 0;
599	    }
600	
601	    /** Whether the claim counts in the live totals: its person's OPEN and PENDING claims dated within a hold do not,
602	     *  unless a statement binds them, nor does a claim deferred past the sheet's today; their other ones do. */
603	    private static boolean counts(Claim claim, Person person, LocalDate today) {
604	        return claim.getStatus().counts() && !held(claim, person, today) && !claim.isDeferredOn(today);
605	    }
606	
607	    /** Whether the claim counts as it would in the live totals were its status {@code then}. */
608	    private static boolean countsAs(Claim claim, ClaimStatus then, Person person, LocalDate today) {
609	        // Held as the live totals hold it: by its status now, not the one it had then.
610	        boolean held = claim.getStatus().isOpen() && !claim.isStated()
611	                && (person.heldOn(claim.getDate()) || person.retiredOn(today));
612	        return then.counts() && !held && !claim.isDeferredOn(today);
613	    }
614	
615	    /** Whether a hold leaves the claim out: it is OPEN or PENDING, unbound, and dated within one of its person's holds
616	     *  or its person's retirement date is reached on the sheet's today. */
617	    public static boolean held(Claim claim, Person person, LocalDate today) {
618	        return claim.getStatus().isOpen() && !claim.isBound()
619	                && (person.heldOn(claim.getDate()) || person.retiredOn(today));
620	    }
621	
622	    private static String show(BigDecimal figure) {
623	        return figure == null ? "n/a" : figure.toPlainString();
624	    }
625	
626	    /** A claim's figure: its settled due, else the figure a statement bound, else its rate figure (the floor comes later, after the late charge). */
627	    private static BigDecimal figure(Claim claim, String grade, List<Rate> sheetRates, LateCharge late) {
628	        if (claim.getSettledDue() != null) {
629	            return claim.getSettledDue().setScale(2);
630	        }
631	        if (claim.isBound()) {
632	            return claim.getStatedDue() == null ? null : claim.getStatedDue().setScale(2);
633	        }
634	        BigDecimal rate = rateOn(sheetRates, grade, claim.getDate());
635	        return claim.figureAt(rate, late.rounding(claim));
636	    }
637	
638	    /** The grade's rate in force on the date, on the sheet or else up its parents (see {@link Rate#on}). */
639	    private static BigDecimal rateOn(List<Rate> sheetRates, String grade, LocalDate on) {
640	        return Rate.on(sheetRates, grade, on);
641	    }
642	}
643	package net.officefloor.hq.app.rollup;
644	
645	import java.math.BigDecimal;
646	
647	/**
648	 * A person's figures: their claimed, their due-total (null: n/a) and their overdue-total, all with two decimals.
649	 */
650	public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
651	
652	    /** Whether the claimed, the due-total or the overdue-total differs from {@code other}'s. */
653	    boolean movedFrom(Figures other) {
654	        return other == null || !claimed.equals(other.claimed) || !java.util.Objects.equals(dueTotal, other.dueTotal)
655	                || !overdueTotal.equals(other.overdueTotal);
656	    }
657	}
658	package net.officefloor.hq.app.claim;
659	
660	/**
661	 * A claim's status: DRAFT → OPEN → SETTLED, and a DRAFT, OPEN or PENDING claim may become VOID. A clerk's settle above
662	 * the clerk limit leaves an OPEN claim PENDING; a steward's review then approves it (SETTLED) or rejects it (OPEN).
663	 * A steward may also void a SETTLED claim within {@link #VOID_SETTLED_DAYS} days of its settlement. A DRAFT claim may be
664	 * DELETED (it counts nowhere and takes no other change), and made a DRAFT again on the same sheet-today it was deleted.
665	 */
666	public enum ClaimStatus {
667	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED;
668	
669	    /** How many days after its settlement (by the sheet's today) a steward may still void a SETTLED claim. */
670	    public static final int VOID_SETTLED_DAYS = 7;
671	
672	    /** Whether a claim in this status may move to {@code next} by an open, settle, void, delete or restore (not a review); a
673	     * SETTLED claim's void is further bound to a steward and its settlement window. */
674	    public boolean canBecome(ClaimStatus next) {
675	        return switch (next) {
676	            case OPEN -> this == DRAFT;
677	            case SETTLED, PENDING -> this == OPEN;
678	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED;
679	            case DELETED -> this == DRAFT;
680	            case DRAFT -> this == DELETED;
681	        };
682	    }
683	
684	    /** Whether a claim in this status counts toward claimed, due and every total. */
685	    public boolean counts() {
686	        return this == OPEN || this == PENDING || this == SETTLED;
687	    }
688	
689	    /** Whether a claim in this status is live: OPEN or PENDING — it goes overdue, and a hold takes it out of the totals. */
690	    public boolean isOpen() {
691	        return this == OPEN || this == PENDING;
692	    }
693	}
