                .filter(c -> c.getId() != claim.getId()
                        && (c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
                        && c.getDueBy() != null && !c.getDueBy().isBefore(period.from()) && !c.getDueBy().isAfter(period.to()))
