2	/**
3	 * Adds a DRAFT claim per pasted line, in order, for the person of that name (case and surrounding spaces ignored).
4	 * Every line is first checked as the claim form checks a new claim (person on the sheet, correction, reference, closed period,
5	 * retirement); one refusal refuses them all before anything is written. Each added claim is recorded as CLAIM_ADDED,
6	 * then the rollup lines for what the paste moved.
7	 */
8	public class AddPastedClaims {
9	    public void add(@Val SheetResponse sheet, @Val PasteLines pasted, @Val ChangedBy by, PersonRepository people,
10	            ClaimRepository claims, SheetRepository sheets, PeriodRepository periods, SettingRepository settings,
11	            HolidayRepository holidays, Rollup rollup, Audit audit, ClaimLog log, Out<PasteResponse> response) throws BadRequestException {
12	        LocalDate today = settings.entryDate(sheet.id(), sheets.today(sheet.id()));
13	        List<Person> persons = new ArrayList<>();
14	        int n = 0;
15	        for (PasteLine line : pasted.lines()) {
16	            n++;
17	            Person person = people.findByName(sheet.id(), line.name());
18	            if (person == null) {
19	                throw new BadRequestException("Line " + n + ": " + line.name() + " is not on this sheet");
20	            }
21	            ClaimInput input = line.input();
22	            LocalDate date = input.date() != null ? input.date() : today;
23	            try {
24	                RefuseBadCorrection.refuse(input, sheet.id(), person.getId(), claims);
25	                RefuseUsedRef.refuse(sheet.id(), input.ref(), -1, claims);
26	                RefuseClosedDate.refuse(sheet.id(), BuildClaim.dueBy(person, date, settings, holidays), periods);
27	                RefuseRetiredDate.refuse(person, date);
28	            } catch (BadRequestException e) {
29	                throw new BadRequestException("Line " + n + ": " + e.getMessage());
30	            }
31	            persons.add(person);
32	        }
33	        RollupSnapshot before = rollup.snapshot(sheet.id());
34	        for (int i = 0; i < persons.size(); i++) {
35	            Person person = persons.get(i);
36	            ClaimInput input = pasted.lines().get(i).input();
37	            LocalDate date = input.date() != null ? input.date() : today;
38	            Claim claim = claims.insert(sheet.id(), person.getId(), input.amount(), date, input.note(),
39	                    input.corrects(), input.ref(), input.tags(), BuildClaim.terms(person, date, settings));
40	            if (periods.softClosedOn(sheet.id(), claim.getDueBy())) {
41	                claims.markLate(claim);
42	            }
43	            audit.record(ClaimAudit.added(claim, by, person.getName()));
44	            if (claim.isLateEntry()) {
45	                audit.record(ClaimAudit.line("LATE_ENTRY", claim, by, person.getName()));
46	            }
47	            log.record(claim, by);
48	        }
49	        rollup.record(sheet.id(), before, by);
50	        response.set(new PasteResponse(persons.size()));
51	    }
52	}
