131	 * Moves the claim to another person on the sheet: by a role the sheet's reassign permission gives (a steward's while blank), and only for a DRAFT, OPEN or PENDING claim, never to its
132	 * own person nor to one retired before the claim's date. It keeps its date and, when numbered, takes the next number of
133	 * the sequence it would be numbered in (its old number is never used again; a draft gets none), loses any figure a statement
134	 * bound it to (live again until its new person's next statement) and is listed as its new person's newest claim.
135	 */
136	public class ApplyReassign {
137	    public void apply(@Val ReassignTo to, @Val Claim claim, @Val ChangedBy by, ClaimRepository repository,
138	            PersonRepository people, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
139	            PeriodRepository periods) throws BadRequestException {
140	        move(to, claim, by, repository, people, roles, settings, sheets, periods, false);
141	    }
142	    /** Moves the claim; in a bulk move ({@code bulk}) one already the person's is moved (relisted) all the same. */
143	    void move(ReassignTo to, Claim claim, ChangedBy by, ClaimRepository repository, PersonRepository people,
144	            RoleRepository roles, SettingRepository settings, SheetRepository sheets, PeriodRepository periods, boolean bulk) throws BadRequestException {
145	        String sheetId = claim.getSheetId();
146	        String role = roles.roleOf(sheetId, by.name());
147	        if (!settings.allows(sheetId, "reassign", role)) {
148	            throw new BadRequestException("A " + role + " may not move a claim to another person on this sheet");
149	        }
150	        ClaimStatus status = claim.getStatus();
151	        if (status != ClaimStatus.DRAFT && !status.isOpen()) {
152	            throw new BadRequestException("A " + status + " claim cannot move to another person");
153	        }
154	        Person target = people.find(sheetId, to.personId());
155	        if (target == null) {
156	            throw new BadRequestException("No such person on this sheet");
157	        }
158	        if (!bulk && target.getId() == claim.getPersonId()) {
159	            throw new BadRequestException("The claim is already that person's");
160	        }
161	        RefuseRetiredDate.refuse(target, claim.getDate());
162	        Person from = people.find(sheetId, claim.getPersonId());
163	        if (!repository.reassign(claim, target.getId())) {
164	            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
165	        }
166	        if (claim.getNumber() != null && !claim.getNumber().isEmpty()) {
167	            // Numbered only once the claim is surely moving, so a refused move uses up no number.
168	            claim.setNumber(ApplyClaimStatus.number(claim, repository, settings, sheets, periods));
169	            repository.updateStatus(claim, claim.getStatus());
170	        }
171	        to.moved(from == null ? "" : from.getName(), target.getName());
172	    }
