552	public final class ClaimNumbering {
553	    private ClaimNumbering() {
554	    }
555	    /**
556	     * The number a claim due by {@code dueBy} takes when opened on the sheet now: while the sheet numbers by period
557	     * and its today is on or after that setting's date, the next within the claim's period (by its due-by) as
558	     * {@code <period name>-<n>}, or {@code X-<n>} in no period; otherwise the tree's next within the fiscal year of its due-by (by the sheet's fiscal
559	     * start month) as {@code FY<yyyy>-<n>}.
560	     */
561	    public static String number(String sheetId, LocalDate dueBy, ClaimRepository repository,
562	            SettingRepository settings, SheetRepository sheets, PeriodRepository periods) {
563	        LocalDate from = settings.periodNumberingFrom(sheetId);
564	        if (from == null || sheets.today(sheetId).isBefore(from)) {
565	            String fy = FiscalYear.of(dueBy, settings.fiscalStartMonth(sheetId)).name();
566	            return fy + "-" + repository.nextFiscalNumber(sheetId, fy);
567	        }
568	        Period period = periods.on(sheetId, dueBy);
569	        return period == null ? "X-" + repository.nextNumber(sheetId, "X")
570	                : period.name() + "-" + repository.nextNumber(sheetId, String.valueOf(period.id()));
