578	/**
579	 * For every plan on the sheet, in the order added, a DRAFT claim with the plan's amount and an empty note for each plan
580	 * date (see Plan#datesThrough) up to its end and the sheet's today that has none yet, dated that day. Each is
581	 * checked as the claim form checks a new claim (closed period, retirement); a date it refuses is skipped, to be tried
582	 * again next time. Each added claim is recorded as CLAIM_ADDED, then the rollup lines for what the generate moved.
583	 */
584	public class GeneratePlanClaims {
585	    public void generate(@Val SheetResponse sheet, @Val ChangedBy by, PlanRepository plans, PersonRepository people,
586	            ClaimRepository claims, SheetRepository sheets, PeriodRepository periods, SettingRepository settings,
587	            HolidayRepository holidays, Rollup rollup, Audit audit, ClaimLog log, Out<GenerateResponse> response) {
588	        LocalDate today = sheets.today(sheet.id());
589	        RollupSnapshot before = rollup.snapshot(sheet.id());
590	        int made = 0;
591	        for (Plan plan : plans.list(sheet.id())) {
592	            Set<LocalDate> done = plans.made(plan.id());
593	            for (LocalDate date : plan.datesThrough(today)) {
594	                if (done.contains(date)) {
595	                    continue;
596	                }
597	                // Re-read each time: an earlier claim may have changed what the rules see.
598	                Person person = people.find(sheet.id(), plan.personId());
599	                try {
600	                    RefuseClosedDate.refuse(sheet.id(), BuildClaim.dueBy(person, date, settings, holidays), periods);
601	                    RefuseRetiredDate.refuse(person, date);
602	                } catch (BadRequestException e) {
603	                    continue;
604	                }
605	                Claim claim = claims.insert(sheet.id(), person.getId(), plan.amount(), date, "", null, null, null,
606	                        BuildClaim.terms(person, date, settings));
607	                if (periods.softClosedOn(sheet.id(), claim.getDueBy())) {
608	                    claims.markLate(claim);
609	                }
610	                plans.markMade(plan, date);
611	                audit.record(ClaimAudit.added(claim, by, person.getName()));
612	                if (claim.isLateEntry()) {
613	                    audit.record(ClaimAudit.line("LATE_ENTRY", claim, by, person.getName()));
614	                }
615	                log.record(claim, by);
616	                made++;
617	            }
618	        }
619	        rollup.record(sheet.id(), before, by);
620	        response.set(new GenerateResponse(made));
621	    }
622	}
