640	/**
641	 * Opens each selected claim in list order — the people in their list positions, each one's claims newest
642	 * first — so they are numbered in that order. Each is opened exactly as opening it alone would (the same refusals,
643	 * the same audit and rollup lines); one that cannot be opened is left as it is and counted as refused.
644	 */
645	public class OpenClaims {
646	    public void open(@Val SheetResponse sheet, @Val BulkOpenIds selected, @Val ChangedBy by, ClaimRepository claims,
647	            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
648	            SheetRepository sheets, PeriodRepository periods, Rollup rollup, Audit audit, ClaimLog log, ClaimLogRepository logs,
649	            WatchRepository watches, VoidReasonRepository voidReasons, Out<BulkOpenResponse> result) {
650	        int opened = 0;
651	        if (roles.isViewer(sheet.id(), by.name()) || sheets.isArchived(sheet.id())) {
652	            // A viewer's press, or one on an archived sheet, goes through with nothing done: every selected claim is
653	            // refused.
654	            result.set(new BulkOpenResponse(0, selected.ids().size()));
655	            return;
656	        }
657	        ApplyClaimStatus apply = new ApplyClaimStatus();
658	        RefuseClosedClaim closed = new RefuseClosedClaim();
659	        RecordClaimStatus record = new RecordClaimStatus();
660	        for (Person person : people.list(sheet.id())) {
661	            for (Claim claim : claims.listOf(sheet.id(), person.getId())) {
662	                if (!selected.ids().contains(claim.getId())) {
663	                    continue;
664	                }
665	                try {
666	                    closed.check(claim, periods);
667	                    RollupSnapshot before = rollup.snapshot(sheet.id());
668	                    ClaimNumber[] number = new ClaimNumber[1];
669	                    Out<ClaimNumber> audited = value -> number[0] = value;
670	                    apply.apply(ClaimStatus.OPEN, claim, claims, people, rates, roles, settings, sheets, periods, logs, by, ClaimReview.NONE, VoidChoice.NONE, voidReasons, audited);
671	                    record.record(claim, number[0], by, ClaimReview.NONE, people, watches, logs, audit, log);
672	                    rollup.record(sheet.id(), before, by);
673	                    opened++;
674	                } catch (BadRequestException refused) {
675	                    // left as it is
676	                }
677	            }
678	        }
679	        // A selected id not on this sheet's list cannot be opened either.
680	        result.set(new BulkOpenResponse(opened, selected.ids().size() - opened));
681	    }
682	}
