700	/**
701	 * Moves each selected claim to the chosen person in list order — the people in their list positions, each one's
702	 * claims newest first, taken before any moves so a moved claim is not met again. Each is moved exactly as moving it
703	 * alone would (the same refusals, the same audit and rollup lines); one that cannot be moved is left as it is and
704	 * counted as refused.
705	 */
706	public class ReassignClaims {
707	    public void reassign(@Val SheetResponse sheet, @Val BulkReassignIds selected, @Val ChangedBy by,
708	            ClaimRepository claims, PersonRepository people, RoleRepository roles, SettingRepository settings,
709	            SheetRepository sheets, PeriodRepository periods, Rollup rollup, Audit audit,
710	            Out<BulkReassignResponse> result) {
711	        int moved = 0;
712	        if (roles.isViewer(sheet.id(), by.name()) || sheets.isArchived(sheet.id())) {
713	            // A viewer's press, or one on an archived sheet, goes through with nothing done: every selected claim is
714	            // refused.
715	            result.set(new BulkReassignResponse(0, selected.ids().size()));
716	            return;
717	        }
718	        List<Claim> ordered = new ArrayList<>();
719	        for (Person person : people.list(sheet.id())) {
720	            for (Claim claim : claims.listOf(sheet.id(), person.getId())) {
721	                if (selected.ids().contains(claim.getId())) {
722	                    ordered.add(claim);
723	                }
724	            }
725	        }
726	        ApplyReassign apply = new ApplyReassign();
727	        RefuseClosedClaim closed = new RefuseClosedClaim();
728	        RecordClaimReassigned record = new RecordClaimReassigned();
729	        for (Claim listed : ordered) {
730	            try {
731	                // re-read: an earlier move relisted the sheet's claims
732	                Claim claim = claims.find(sheet.id(), listed.getId());
733	                if (claim == null) {
734	                    continue;
735	                }
736	                closed.check(claim, periods);
737	                RollupSnapshot before = rollup.snapshot(sheet.id());
738	                ReassignTo to = new ReassignTo(selected.personId());
739	                apply.move(to, claim, by, claims, people, roles, settings, sheets, periods, true);
740	                record.record(claim, to, by, audit);
741	                rollup.record(sheet.id(), before, by);
742	                moved++;
