923	 * Re-dates each selected claim to the chosen date in list order — the people in their list positions, each one's
924	 * claims newest first. Each is re-dated exactly as re-dating it alone would (the same refusals, the same audit and
925	 * rollup lines); one that cannot be re-dated is left as it is and counted as refused.
926	 */
927	public class RedateClaims {
928	    public void redate(@Val SheetResponse sheet, @Val BulkRedateIds selected, @Val ChangedBy by,
929	            ClaimRepository claims, PersonRepository people, RoleRepository roles, SheetRepository sheets,
930	            PeriodRepository periods, Rollup rollup, Audit audit, Out<BulkRedateResponse> result) {
931	        int redated = 0;
932	        if (roles.isViewer(sheet.id(), by.name()) || sheets.isArchived(sheet.id())) {
933	            // A viewer's press, or one on an archived sheet, goes through with nothing done: every selected claim is
934	            // refused.
935	            result.set(new BulkRedateResponse(0, selected.ids().size()));
936	            return;
937	        }
938	        List<Claim> ordered = new ArrayList<>();
939	        for (Person person : people.list(sheet.id())) {
940	            for (Claim claim : claims.listOf(sheet.id(), person.getId())) {
941	                if (selected.ids().contains(claim.getId())) {
942	                    ordered.add(claim);
943	                }
944	            }
945	        }
946	        ApplyRedate apply = new ApplyRedate();
947	        RefuseClosedClaim closed = new RefuseClosedClaim();
948	        RecordClaimRedated record = new RecordClaimRedated();
949	        for (Claim listed : ordered) {
950	            try {
951	                Claim claim = claims.find(sheet.id(), listed.getId());
952	                if (claim == null) {
953	                    continue;
954	                }
955	                closed.check(claim, periods);
956	                RollupSnapshot before = rollup.snapshot(sheet.id());
957	                RedateTo to = new RedateTo(selected.date());
958	                apply.apply(to, claim, by, claims, people, roles);
959	                record.record(claim, to, by, people, audit);
960	                rollup.record(sheet.id(), before, by);
961	                redated++;
962	            } catch (BadRequestException refused) {
963	                // left as it is
964	            }
965	        }
966	        // A selected id not on this sheet's list cannot be re-dated either.
967	        result.set(new BulkRedateResponse(redated, selected.ids().size() - redated));
