423	/**
424	 * A person's plan: an amount, a start date, every N days or a day of the month (exactly one set) and an end date (not
425	 * before the start), and how many claims it has made so far.
426	 */
427	public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
428	        Integer day, LocalDate end, int generated) {
429	    /**
430	     * Its dates up to the end and {@code until}, earliest first: the start, then every N days; or, monthly, the day in
431	     * every month from the start's month (a day beyond the month's length on its last day), those before the start left
432	     * out.
433	     */
434	    public List<LocalDate> datesThrough(LocalDate until) {
435	        List<LocalDate> dates = new ArrayList<>();
436	        LocalDate last = end.isBefore(until) ? end : until;
437	        if (day != null) {
438	            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
439	                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
440	                if (!d.isBefore(start) && !d.isAfter(last)) {
441	                    dates.add(d);
442	                }
443	            }
444	            return dates;
445	        }
446	        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
447	            dates.add(d);
448	        }
449	        return dates;
450	    }
451	    /** Its first five dates after {@code today} and on or before the end, earliest first. */
452	    public List<LocalDate> nextDates(LocalDate today) {
453	        return datesThrough(end).stream().filter(d -> d.isAfter(today)).limit(5).toList();
454	    }
455	}
