546	/**
547	 * A plan's fields: an amount by the claim form's rule (0.00 or more), a start date (blank: the sheet's today), every N
548	 * days (a whole number, at least 1) or instead a day of the month (a whole number, 1 to 31) and an end date
549	 * (required, not before the start). Publishes them parsed, with the
550	 * user making the change.
551	 */
552	public class ValidatePlan {
553	    static final String END_BEFORE_START = "A plan's end date is before its start date";
554	    public void validate(@RequestBody PlanRequest request, Out<PlanInput> plan, Out<ChangedBy> changedBy)
555	            throws BadRequestException {
556	        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
557	        BigDecimal amount = ClaimAmount.of(request == null ? null : request.amount());
558	        String startText = request == null || request.start() == null ? "" : request.start().trim();
559	        LocalDate start = startText.isEmpty() ? null : date(startText);
560	        String everyText = request == null || request.every() == null ? "" : request.every().trim();
561	        String dayText = request == null || request.day() == null ? "" : request.day().trim();
562	        Integer every = null;
563	        Integer day = null;
564	        if (!dayText.isEmpty()) {
565	            if (!everyText.isEmpty()) {
566	                throw new BadRequestException("Give a plan either every N days or a day of the month, not both");
567	            }
568	            if (!dayText.matches("\\d{1,2}") || Integer.parseInt(dayText) < 1 || Integer.parseInt(dayText) > 31) {
569	                throw new BadRequestException("A day of the month is a whole number from 1 to 31");
570	            }
571	            day = Integer.parseInt(dayText);
572	        } else {
573	            if (!everyText.matches("\\d{1,6}") || Integer.parseInt(everyText) < 1) {
574	                throw new BadRequestException("Every is a whole number of days, at least 1");
575	            }
576	            every = Integer.parseInt(everyText);
577	        }
578	        String endText = request == null || request.end() == null ? "" : request.end().trim();
579	        if (endText.isEmpty()) {
580	            throw new BadRequestException("Enter a plan's end date");
581	        }
582	        LocalDate end = date(endText);
583	        if (start != null && end.isBefore(start)) {
584	            throw new BadRequestException(END_BEFORE_START);
585	        }
586	        plan.set(new PlanInput(amount, start, every, day, end));
587	        changedBy.set(by);
588	    }
589	    private static LocalDate date(String text) throws BadRequestException {
590	        try {
591	            return LocalDate.parse(text);
592	        } catch (DateTimeParseException e) {
593	            throw new BadRequestException("Enter a date as YYYY-MM-DD");
594	        }
595	    }
596	}
