13	/**
14	 * Imports the lines, in order. A line whose name is a person's name or alias on the sheet (as names are compared)
15	 * updates that person; any other line adds one. Every line is first checked as the person form checks it — an add as
16	 * a new person (name or alias in use on the sheet or its tree, contact another person's), an update as an edit keeping
17	 * the person's name (two lines naming the same person refuse it too); one refusal refuses them all before anything is
18	 * written. Each is then saved as the form saves it: an add writes PERSON_ADDED, an update gives the grade from the
19	 * sheet's today, sets the terms and contact the line gives (blank keeps them) and writes PERSON_EDITED; then the
20	 * rollup lines it moved.
21	 */
22	public class AddImportedPeople {
23	    public void add(@Val SheetResponse sheet, @Val ImportedPeople imported, @Val ChangedBy by,
24	            PersonRepository repository, SheetRepository sheets, Rollup rollup, Audit audit,
25	            Out<ImportPeopleResponse> response) throws BadRequestException, ConflictException {
26	        List<Person> matched = new ArrayList<>();
27	        Set<Long> seen = new HashSet<>();
28	        int n = 0;
29	        for (PersonRequest request : imported.people()) {
30	            n++;
31	            Person person = repository.findByName(sheet.id(), request.name());
32	            if (person == null) {
33	                if (repository.nameTaken(sheet.id(), request.name(), null)) {
34	                    throw new BadRequestException("Line " + n + ": " + PersonRepository.NAME_TAKEN);
35	                }
36	                if (repository.contactTaken(sheet.id(), request.contactOrNull(), null)) {
37	                    throw new BadRequestException("Line " + n + ": " + PersonRepository.CONTACT_TAKEN);
38	                }
39	            } else {
40	                if (!seen.add(person.getId())) {
41	                    throw new BadRequestException("Line " + n + ": " + person.getName() + " is repeated in the import");
42	                }
43	                try {
44	                    new CheckPersonRename().check(sheet, edit(request, person), person, repository);
45	                } catch (BadRequestException e) {
46	                    throw new BadRequestException("Line " + n + ": " + e.getMessage());
47	                }
48	            }
49	            matched.add(person);
50	        }
51	        LocalDate today = sheets.today(sheet.id());
52	        int added = 0;
53	        int updated = 0;
54	        for (int i = 0; i < imported.people().size(); i++) {
55	            PersonRequest request = imported.people().get(i);
56	            Person person = matched.get(i);
57	            RollupSnapshot before = rollup.snapshot(sheet.id());
58	            if (person == null) {
59	                person = repository.insert(sheet.id(), request.name(), request.grade(), request.termsDays(),
60	                        request.contactOrNull());
61	                new RecordPersonAdded().record(person, by, audit);
62	                added++;
63	            } else {
64	                PersonRequest edit = edit(request, person);
65	                Integer termsBefore = person.getTerms();
66	                String contactBefore = person.getContact();
67	                person.setTerms(edit.termsDays());
68	                person.setContact(edit.contactOrNull());
69	                if (!repository.update(person)) {
70	                    throw new ConflictException(PersonRepository.CHANGED);
71	                }
72	                repository.giveGrade(person, edit.grade(), today, today);
73	                new RecordPersonEdited().record(person, by,
74	                        new TermsEdit(!Objects.equals(termsBefore, person.getTerms())),
75	                        new ContactEdit(!Objects.equals(contactBefore, person.getContact())), audit);
76	                updated++;
77	            }
78	            rollup.record(sheet.id(), before, by);
79	        }
80	        response.set(new ImportPeopleResponse(added, updated));
81	    }
82	    /** The line as the form's edit of the person: their name kept, and their terms and contact kept when blank. */
83	    private static PersonRequest edit(PersonRequest request, Person person) {
84	        String terms = request.termsDays() != null ? request.terms()
85	                : person.getTerms() == null ? "" : String.valueOf(person.getTerms());
86	        String contact = request.contactOrNull() != null ? request.contact()
87	                : person.getContact() == null ? "" : person.getContact();
88	        return new PersonRequest(person.getName(), request.grade(), request.by(), person.getVersion(), "", terms,
89	                contact, person.getTags() == null ? "" : person.getTags());
90	    }
91	}
