230	##### GradePeople.java
231	/**
232	 * Gives each selected person the grade in list order — the people in their list positions — exactly as saving
233	 * it on the person form would: the grade from the from-date (the sheet's today when blank), their name and terms kept,
234	 * a PERSON_EDITED line and the rollup lines it moved. A selected id not on this sheet is skipped. A viewer changes no one.
235	 */
236	public class GradePeople {
237	    public void grade(@Val SheetResponse sheet, @Val BulkGrade bulk, @Val ChangedBy by, PersonRepository people,
238	            SheetRepository sheets, RoleRepository roles, Rollup rollup, Audit audit, Out<BulkGradeResponse> result)
239	            throws ConflictException {
240	        if (roles.isViewer(sheet.id(), by.name())) {
241	            result.set(new BulkGradeResponse(0));
242	            return;
243	        }
244	        ApplyPerson apply = new ApplyPerson();
245	        RecordPersonEdited record = new RecordPersonEdited();
246	        int changed = 0;
247	        for (Person person : people.list(sheet.id())) {
248	            if (!bulk.ids().contains(person.getId())) {
249	                continue;
250	            }
251	            PersonRequest request = new PersonRequest(person.getName(), bulk.grade(), by.name(), person.getVersion(),
252	                    bulk.from(), person.getTerms() == null ? "" : String.valueOf(person.getTerms()),
253	                    person.getContact() == null ? "" : person.getContact(),
254	                    person.getTags() == null ? "" : person.getTags());
255	            RollupSnapshot before = rollup.snapshot(sheet.id());
256	            TermsEdit[] terms = new TermsEdit[1];
257	            ContactEdit[] contact = new ContactEdit[1];
258	            apply.apply(request, person, people, sheets, value -> terms[0] = value, value -> contact[0] = value);
259	            record.record(person, by, terms[0], contact[0], audit);
260	            rollup.record(sheet.id(), before, by);
261	            changed++;
262	        }
263	        result.set(new BulkGradeResponse(changed));
264	    }
265	}
