351	public class MergePerson {
352	    public void merge(@Val MergeInput input, @Val Person person, @Val ChangedBy by, PersonRepository repository,
353	            RoleRepository roles, Out<PersonMerged> merged) throws BadRequestException {
354	        if (!Role.STEWARD.equals(roles.roleOf(person.getSheetId(), by.name()))) {
355	            throw new BadRequestException("Only a steward may merge people");
