649	/**
650	 * Retires each selected person from the date (the sheet's today when blank) in list order — the people in their list
651	 * positions — as the row's retire does: a PERSON_RETIRED line and the rollup lines it moved. A person retired already
652	 * is retired from the new date instead. A selected id not on this sheet is skipped. A viewer retires no one.
653	 */
654	public class RetirePeople {
655	    public void retire(@Val SheetResponse sheet, @Val BulkRetire bulk, @Val ChangedBy by, PersonRepository people,
656	            SheetRepository sheets, RoleRepository roles, Rollup rollup, Audit audit, Out<BulkRetireResponse> result) {
657	        if (roles.isViewer(sheet.id(), by.name())) {
658	            result.set(new BulkRetireResponse(0));
659	            return;
660	        }
661	        LocalDate from = bulk.date() != null ? bulk.date() : sheets.today(sheet.id());
662	        RecordPersonRetired record = new RecordPersonRetired();
663	        int retired = 0;
664	        for (Person person : people.list(sheet.id())) {
665	            if (!bulk.ids().contains(person.getId())) {
666	                continue;
667	            }
668	            RollupSnapshot before = rollup.snapshot(sheet.id());
669	            people.retireFrom(person.getId(), from);
670	            person.setRetiredFrom(from);
671	            record.record(person, by, audit);
672	            rollup.record(sheet.id(), before, by);
673	            retired++;
674	        }
675	        result.set(new BulkRetireResponse(retired));
676	    }
677	}
