679	/** Retires the person from the date (blank: the sheet's today); refuses a person already retired. */
680	public class RetirePerson {
681	    public void retire(@Val RetireInput input, @Val Person person, PersonRepository repository, SheetRepository sheets)
682	            throws BadRequestException {
683	        if (person.isRetired()) {
684	            throw new BadRequestException("That person is already retired");
685	        }
