734	##### TransferPerson.java
735	/**
736	 * Transfers the person to another sheet by id: only a steward may, never a retired person, never to this sheet itself
737	 * nor to an archived one. When their name or one of their aliases is a name or alias of a person on the other sheet,
738	 * they are merged into that person there (see {@link PersonRepository#transferInto}) — never into a retired one, nor
739	 * when their names are those of more than one person there; otherwise not while one of their names is in use in the
740	 * other sheet's tree, nor while their contact is already on the other sheet. Each claim of theirs that had a number takes the other sheet's next one, in the order the claims were opened
741	 * (by the sheet's today when each was opened, then by the order they were added). See
742	 * {@link PersonRepository#transfer} for what moves and what is dropped.
743	 */
744	public class TransferPerson {
745	    public void transfer(@Val TransferInput input, @Val Person person, @Val ChangedBy by, PersonRepository repository,
746	            RoleRepository roles, SheetRepository sheets, ClaimRepository claims, ClaimLogRepository log,
747	            SettingRepository settings, PeriodRepository periods, Rollup rollup, Out<PersonTransferred> transferred)
748	            throws BadRequestException {
749	        String sheetId = person.getSheetId();
750	        String to = input.to();
751	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, by.name()))) {
752	            throw new BadRequestException("Only a steward may transfer people");
753	        }
754	        if (to.equals(sheetId)) {
755	            throw new BadRequestException("A person cannot be transferred to their own sheet");
756	        }
757	        if (person.isRetired()) {
758	            throw new BadRequestException("A retired person cannot be transferred");
759	        }
760	        if (sheets.isArchived(to)) {
761	            throw new BadRequestException("That sheet is archived");
762	        }
763	        Person into = null;
764	        List<String> names = new java.util.ArrayList<>();
765	        names.add(person.getName());
766	        names.addAll(person.getAliases());
767	        for (String name : names) {
768	            Person match = repository.findByName(to, name);
769	            if (match != null && into != null && match.getId() != into.getId()) {
770	                throw new BadRequestException("Their names are in use by more than one person on the other sheet");
771	            }
772	            if (match != null) {
773	                into = match;
774	            }
775	        }
776	        for (String name : names) {
777	            if (into == null || repository.findByName(to, name) == null) {
778	                if (repository.nameTaken(to, name, person.getId())) {
779	                    throw new BadRequestException(name.equals(person.getName())
780	                            ? "That name is already in use on the other sheet"
781	                            : "The alias " + name + " is already in use on the other sheet");
782	                }
783	            }
784	        }
785	        if (into != null && into.isRetired()) {
786	            throw new BadRequestException("A retired person cannot be merged");
787	        }
788	        if (into == null && repository.contactTaken(to, person.getContact(), null)) {
789	            throw new BadRequestException("That contact is already another person's on the other sheet");
790	        }
791	        if (!repository.touch(person)) {
792	            throw new BadRequestException("Someone else has changed this person; reload the sheet");
793	        }
794	        sheets.ensure(to);
795	        var before = rollup.snapshot(to);
796	        List<Claim> own = claims.listOf(sheetId, person.getId());
797	        Map<Long, LocalDate> opened = new LinkedHashMap<>();
798	        for (Claim claim : own) {
799	            if (claim.getNumber() != null) {
800	                LocalDate on = log.firstOn(sheetId, claim.getId(), ClaimStatus.OPEN);
801	                opened.put(claim.getId(), on != null ? on : claim.getDate());
802	            }
803	        }
804	        List<Claim> numbered = own.stream()
805	                .filter(c -> opened.containsKey(c.getId()))
806	                .sorted(Comparator.<Claim, LocalDate>comparing(c -> opened.get(c.getId())).thenComparing(Claim::getId))
807	                .toList();
808	        Map<Long, String> numbers = new LinkedHashMap<>();
809	        for (Claim claim : numbered) {
810	            numbers.put(claim.getId(), ClaimNumbering.number(to, claim.getDueBy(), claims, settings, sheets, periods));
811	        }
812	        if (into == null) {
813	            repository.transfer(person, to, numbers);
814	        } else if (!repository.transferInto(person, into, numbers)) {
815	            throw new BadRequestException("Someone else has changed the person on the other sheet; reload the sheet");
816	        }
817	        transferred.set(new PersonTransferred(person.getName(), to, before, into == null ? null : into.getName()));
818	    }
819	}
