953	/**
954	 * The import box's lines of name,grade,terms,contact (terms and contact may be absent or blank; blank lines are
955	 * skipped). Each line's fields are checked with the person form's rules; a name (ignoring case) or contact repeated
956	 * within the import refuses it. A refusal names the line. Publishes them parsed, in order, with the user making the
957	 * change.
958	 */
959	public class ValidateImportPeople {
960	    static final int MAX_LINES = 1000;
961	    public void validate(@RequestBody ImportPeopleRequest request, Out<ImportedPeople> imported,
962	            Out<ChangedBy> changedBy) throws BadRequestException {
963	        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
964	        String text = request == null || request.lines() == null ? "" : request.lines();
965	        List<PersonRequest> people = new ArrayList<>();
966	        Set<String> names = new HashSet<>();
967	        Set<String> contacts = new HashSet<>();
968	        String[] typed = text.split("\\r?\\n");
969	        for (int i = 0; i < typed.length; i++) {
970	            if (typed[i].trim().isEmpty()) {
971	                continue;
972	            }
973	            String[] fields = typed[i].split(",", -1);
974	            if (fields.length < 2 || fields.length > 4) {
975	                throw new BadRequestException("Line " + (i + 1) + ": enter name,grade,terms,contact");
976	            }
977	            try {
978	                PersonRequest person = ValidatePerson.parse(new PersonRequest(fields[0], fields[1], by.name(), null,
979	                        "", fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : "", ""), by);
980	                if (!names.add(person.name().toLowerCase(Locale.ROOT))) {
981	                    throw new BadRequestException(person.name() + " is repeated in the import");
982	                }
983	                if (person.contactOrNull() != null && !contacts.add(person.contact())) {
984	                    throw new BadRequestException("The contact " + person.contact() + " is repeated in the import");
985	                }
986	                people.add(person);
987	            } catch (BadRequestException e) {
988	                throw new BadRequestException("Line " + (i + 1) + ": " + e.getMessage());
989	            }
990	        }
991	        if (people.isEmpty()) {
992	            throw new BadRequestException("Paste at least one line of name,grade,terms,contact");
993	        }
994	        if (people.size() > MAX_LINES) {
995	            throw new BadRequestException("Import at most " + MAX_LINES + " lines at once");
996	        }
997	        imported.set(new ImportedPeople(people));
998	        changedBy.set(by);
999	    }
1000	}
