1145	/** Which users watch which people; a person's watchers are kept in the order they started watching. */
1146	@Repository
1147	public class WatchRepository {
1148	    private final JdbcTemplate jdbc;
1149	    public WatchRepository(JdbcTemplate jdbc) {
1150	        this.jdbc = jdbc;
1151	    }
1152	    /** The users watching the person, in the order they started watching. */
1153	    public List<String> watchers(long personId) {
1154	        return jdbc.queryForList("SELECT user_name FROM person_watch WHERE person_id = ? ORDER BY id", String.class,
1155	                personId);
1156	    }
1157	    /** The ids of the people on the sheet the user watches. */
1158	    public List<Long> watchedBy(String sheetId, String user) {
1159	        return jdbc.queryForList("SELECT w.person_id FROM person_watch w JOIN person p ON p.id = w.person_id"
1160	                + " WHERE p.sheet_id = ? AND w.user_name = ? ORDER BY w.person_id", Long.class, sheetId, user);
1161	    }
1162	    /** Start the user watching the person; false when they already were. */
1163	    public boolean watch(long personId, String user) {
1164	        if (isWatching(personId, user)) {
1165	            return false;
1166	        }
1167	        jdbc.update("INSERT INTO person_watch (person_id, user_name) VALUES (?, ?)", personId, user);
1168	        return true;
1169	    }
1170	    /** Stop the user watching the person; false when they were not. */
1171	    public boolean unwatch(long personId, String user) {
1172	        return jdbc.update("DELETE FROM person_watch WHERE person_id = ? AND user_name = ?", personId, user) > 0;
