252	/**
253	 * The late charge as of the sheet's today: an OPEN (or PENDING) claim past its due-by (the terms-th business day after its date, by the terms fixed when it was added and the sheet's holidays now)
254	 * plus its grade's grace (see {@link #lateFrom}) gains, for every
255	 * full 30 days it is overdue, the late percent in force on that boundary date (that date plus 30, 60, 90 ... days) of its figure
256	 * plus the charges of the boundaries before it (compounding),
257	 * each rounded to two decimals as the claim rounds (see {@link #rounding}), the charges added up. A correction
258	 * (a negative amount) never gains one. The charge is never bound by a statement; settling freezes it into the settled due.
259	 * The floor is applied last: a claim's live due is the greater of the floor in force on its date and its figure plus its
260	 * late charge (a correction has no floor).
261	 */
262	public record LateCharge(LocalDate today, DatedSettings settings, LocalDate policyDate, Map<Long, Person> people) {
263	
264	    /**
265	     * The date the claim's lateness counts from: its due-by plus the grace in force on its date of its person's grade
266	     * on that date (none while blank). It is overdue once this is before today; the 30-day boundaries count from it.
267	     */
268	    public LocalDate lateFrom(Claim claim) {
269	        LocalDate dueBy = claim.getDueBy();
270	        Person person = people.get(claim.getPersonId());
271	        if (dueBy == null || person == null) {
272	            return dueBy;
273	        }
274	        return dueBy.plusDays(settings.grace(person.gradeOn(claim.getDate()), claim.getDate()));
275	    }
276	
277	    /** Whether the claim is overdue as of today: OPEN or PENDING, and its due-by plus its grace before today. */
278	    public boolean overdue(Claim claim) {
279	        LocalDate from = lateFrom(claim);
280	        return claim.getStatus().isOpen() && from != null && from.isBefore(today);
281	    }
282	
283	    /**
284	     * How the claim's live figures round: half up when it is dated before the policy date, half to even on or after
285	     * it. A correction rounds by the date of the claim it corrects.
286	     */
287	    public RoundingMode rounding(Claim claim) {
288	        return claim.getRoundOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
289	    }
290	
291	    /** The claim's late charge on its figure (zero when it is not overdue, is deferred past today, or has no figure). */
292	    public BigDecimal on(Claim claim, BigDecimal figure) {
293	        BigDecimal none = BigDecimal.ZERO.setScale(2);
294	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(today)) {
295	            return none;
296	        }
297	        return onAsOpen(claim, figure);
298	    }
299	
300	    /** The late charge the claim would have on its figure were it OPEN. */
301	    public BigDecimal onAsOpen(Claim claim, BigDecimal figure) {
302	        BigDecimal none = BigDecimal.ZERO.setScale(2);
303	        if (figure == null || claim.isCorrection()) {
304	            return none;
305	        }
306	        LocalDate from = lateFrom(claim);
307	        long overdue = ChronoUnit.DAYS.between(from, today);
308	        long periods = overdue > 0 ? overdue / 30 : 0;
309	        if (periods == 0) {
310	            return none;
311	        }
312	        BigDecimal charge = none;
313	        for (long n = 1; n <= periods; n++) {
314	            BigDecimal pct = settings.latePct(from.plusDays(30 * n));
315	            if (pct.signum() != 0) {
316	                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding(claim)));
317	            }
318	        }
319	        return charge;
320	    }
321	
322	    /**
323	     * The claim's due: its settled due as it is; else the greater of the floor in force on its date and the figure with
324	     * its late charge added on top (a correction has no floor); null without a figure.
325	     */
326	    public BigDecimal due(Claim claim, BigDecimal figure) {
327	        if (figure == null) {
328	            return null;
329	        }
330	        if (claim.getSettledDue() != null) {
331	            return figure.setScale(2);
332	        }
333	        return floored(claim, figure.setScale(2).add(on(claim, figure)));
334	    }
335	
336	    /** The due the claim would have were it OPEN (floored as {@link #due}); null without a figure. */
337	    public BigDecimal dueAsOpen(Claim claim, BigDecimal figure) {
338	        return figure == null ? null : floored(claim, figure.setScale(2).add(onAsOpen(claim, figure)));
339	    }
340	
341	    /** At least the floor in force on the claim's date, unless it is a correction. */
342	    private BigDecimal floored(Claim claim, BigDecimal due) {
343	        return claim.isCorrection() ? due : due.max(settings.floor(claim.getDate()));
344	    }
345	}
