39	    /**
40	     * Swap the person with the one above (up) or below them in the sheet's list; answers the person's new place in
41	     * the list, counting from 1, or null (nothing written) when there is no one there to swap with.
42	     */
43	    public Integer move(Person person, boolean up) {
44	        String sheetId = person.getSheetId();
45	        List<Long> order = jdbc.queryForList(
46	                "SELECT id FROM person WHERE sheet_id = ? ORDER BY list_position, id", Long.class, sheetId);
47	        int at = order.indexOf(person.getId());
48	        int to = up ? at - 1 : at + 1;
49	        if (at < 0 || to < 0 || to >= order.size()) {
50	            return null;
51	        }
52	        java.util.Collections.swap(order, at, to);
53	        // Renumber the whole list, so the swap holds even where positions were equal.
54	        for (int i = 0; i < order.size(); i++) {
55	            jdbc.update("UPDATE person SET list_position = ? WHERE id = ?", i + 1, order.get(i));
56	        }
57	        return to + 1;
58	    }
