96	    /** The names and aliases (lower case, trimmed) of everyone, but that person, on the other sheets of the sheet's tree. */
97	    public java.util.Set<String> namesInTree(String sheetId, Long exceptId) {
98	        java.util.Set<String> found = new java.util.HashSet<>();
99	        long except = exceptId == null ? -1L : exceptId;
100	        for (String other : treeOf(sheetId)) {
101	            found.addAll(jdbc.queryForList("SELECT name_key FROM person WHERE sheet_id = ? AND id <> ?", String.class,
102	                    other, except));
103	            found.addAll(jdbc.queryForList("SELECT alias_key FROM person_alias WHERE sheet_id = ? AND person_id <> ?",
104	                    String.class, other, except));
105	        }
106	        return found;
107	    }
108	    /** The other sheets of the sheet's tree, among the sheets that exist: its parent, theirs and so on up, and its
109	     *  children, theirs and so on down (each once, the sheet itself never among them). */
110	    public List<String> treeOf(String sheetId) {
111	        java.util.Set<String> seen = new java.util.LinkedHashSet<>(List.of(sheetId));
112	        for (String at = parentOf(sheetId); at != null && seen.add(at); at = parentOf(at)) {
113	        }
114	        java.util.Deque<String> todo = new java.util.ArrayDeque<>(List.of(sheetId));
115	        while (!todo.isEmpty()) {
116	            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting_key = 'parent'"
117	                    + " AND setting_value = ? ORDER BY sheet_id", String.class, todo.poll())) {
118	                if (seen.add(child)) {
119	                    todo.add(child);
120	                }
121	            }
122	        }
123	        seen.remove(sheetId);
124	        return seen.stream().filter(s -> jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, s) > 0)
125	                .toList();
126	    }
127	    private String parentOf(String sheetId) {
128	        return jdbc.query("SELECT setting_value FROM sheet_setting WHERE sheet_id = ? AND setting_key = 'parent'",
129	                (rs, n) -> rs.getString(1), sheetId).stream().filter(v -> v != null && !v.isBlank()).findFirst()
130	                .orElse(null);
131	    }
