173	                            + " (SELECT COALESCE(MAX(q.list_position), 0) + 1 FROM person q WHERE q.sheet_id = ?))",
174	                    new String[] { "id" });
175	            ps.setString(1, sheetId);
176	            ps.setString(2, name);
177	            ps.setObject(3, terms, java.sql.Types.INTEGER);
178	            ps.setString(4, contact);
179	            ps.setString(5, tags);
180	            ps.setString(6, sheetId);
181	            return ps;
182	        }, keys);
183	        long id = keys.getKey().longValue();
184	        jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) VALUES (?, ?, NULL)", id, grade);
185	        Person person = new Person(id, sheetId, name, grade, 0);
186	        person.setGrades(List.of(new GradeFrom(grade, null)));
187	        person.setTerms(terms);
