262	    /**
263	     * Merge the person into the other, both still at the versions they were loaded at: the merged person's claims move
264	     * to the other (numbers and dates kept, listed after the other's claims in the order they were added, each
265	     * keeping any figure a statement bound it to); their statements become the other's, taken before the other's own
266	     * (see {@link #carryStatements}); their name and aliases become the other's aliases; their patrons are added
267	     * to the other's and anyone naming them as patron names the other instead (never the other themselves, no
268	     * repeats); their plans and pool memberships move to the other (shares added where the other is a member already) and their
269	     * closed periods' totals add to the other's. Their holds, watchers, grades and contact are dropped
270	     * with them. False (nothing written) when either was saved by someone else in the meantime.
271	     */
272	    public boolean merge(Person from, Person into) {
273	        String sheetId = from.getSheetId();
274	        long f = from.getId();
275	        long t = into.getId();
276	        if (jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND version = ?", t, into.getVersion()) == 0
277	                || jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND version = ?", f,
278	                        from.getVersion()) == 0) {
279	            return false;
280	        }
281	        for (Long claimId : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id",
282	                Long.class, sheetId, f)) {
283	            Long listed = jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE "
284	                    + "(UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)", Long.class, sheetId);
285	            jdbc.update("UPDATE claim SET person_id = ?, listed = ? WHERE id = ?", t,
286	                    listed, claimId);
287	        }
288	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", t, sheetId, f);
289	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, t,
290	                from.getName());
291	        jdbc.update("INSERT INTO person_patron (person_id, patron_id) SELECT ?, pp.patron_id FROM person_patron pp"
292	                + " WHERE pp.person_id = ? AND pp.patron_id <> ? AND NOT EXISTS"
293	                + " (SELECT 1 FROM person_patron o WHERE o.person_id = ? AND o.patron_id = pp.patron_id)"
294	                + " ORDER BY pp.named", t, f, t, t);
295	        jdbc.update("INSERT INTO person_patron (person_id, patron_id, named) SELECT pp.person_id, ?, pp.named FROM person_patron pp"
296	                + " WHERE pp.patron_id = ? AND pp.person_id <> ? AND NOT EXISTS"
297	                + " (SELECT 1 FROM person_patron o WHERE o.person_id = pp.person_id AND o.patron_id = ?)", t, f, t, t);
298	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", f, f);
299	        jdbc.update("UPDATE pool_member m SET share = share + (SELECT o.share FROM pool_member o WHERE o.pool_id = m.pool_id"
300	                + " AND o.person_id = ?) WHERE m.person_id = ? AND EXISTS (SELECT 1 FROM pool_member o"
301	                + " WHERE o.pool_id = m.pool_id AND o.person_id = ?)", f, t, f);
302	        jdbc.update("DELETE FROM pool_member m WHERE m.person_id = ? AND EXISTS (SELECT 1 FROM pool_member o"
303	                + " WHERE o.pool_id = m.pool_id AND o.person_id = ?)", f, t);
304	        jdbc.update("UPDATE pool_member SET person_id = ? WHERE person_id = ?", t, f);
305	        jdbc.update("UPDATE plan SET person_id = ? WHERE person_id = ?", t, f);
306	        jdbc.update("UPDATE period_person_total m SET total = total + (SELECT o.total FROM period_person_total o"
307	                + " WHERE o.period_id = m.period_id AND o.person_id = ?) WHERE m.person_id = ? AND EXISTS"
308	                + " (SELECT 1 FROM period_person_total o WHERE o.period_id = m.period_id AND o.person_id = ?)", f, t, f);
309	        jdbc.update("DELETE FROM period_person_total m WHERE m.person_id = ? AND EXISTS (SELECT 1 FROM period_person_total o"
310	                + " WHERE o.period_id = m.period_id AND o.person_id = ?)", f, t);
311	        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE person_id = ?", t, f);
312	        carryStatements(f, sheetId, t);
313	        jdbc.update("UPDATE person_snapshot SET person_id = ? WHERE person_id = ?", t, f);
314	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", f);
315	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", f);
316	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", f);
317	        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", f);
318	        jdbc.update("DELETE FROM person WHERE id = ?", f);
319	        return true;
320	    }
