330	    /**
331	     * Transfer the person to the other sheet (stored already): they are added there with their name, terms, contact,
332	     * every grade they were given (with its from-date) and their aliases, noting this sheet as the one they came from; their claims move with them (status, dates,
333	     * notes, settled figures, logs, comments and lines kept), listed there in the order they were listed here, each keeping
334	     * any figure a statement bound it to, without its reference or settle batch, and numbered by {@code numbers} (by claim id;
335	     * a claim absent keeps no number), a correction or split naming its claim by the new number; their tags are noted
336	     * as used there; their statements move with them. Everything else of theirs here — patron links either way, pool
337	     * memberships, plans, watches, holds and closed periods' totals — is dropped with them. Answers the person's id on the other sheet.
338	     */
339	    public long transfer(Person from, String toSheet, Map<Long, String> numbers) {
340	        long f = from.getId();
341	        String grade = from.getGrade() != null ? from.getGrade() : from.getGrades().get(0).grade();
342	        long t = insert(toSheet, from.getName(), grade, from.getTerms(), from.getContact(), from.getTags()).getId();
343	        jdbc.update("UPDATE person SET origin = ? WHERE id = ?", from.getSheetId(), t);
344	        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", t);
345	        jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) SELECT ?, grade, from_date FROM person_grade"
346	                + " WHERE person_id = ?", t, f);
347	        jdbc.update("UPDATE person_alias SET sheet_id = ?, person_id = ? WHERE person_id = ?", toSheet, t, f);
348	        moveClaims(from, toSheet, t, numbers);
349	        carryStatements(f, toSheet, t);
350	        dropRest(f);
351	        return t;
352	    }
