356	     * after the other's claims, and their statements become the other's as {@link #merge} carries them; their name and
357	     * aliases become the other's aliases; everything else of theirs is dropped with them (grades, terms and contact
358	     * too). False (nothing written) when the other was saved by someone else in the meantime.
359	     */
360	    public boolean transferInto(Person from, Person into, Map<Long, String> numbers) {
361	        long f = from.getId();
362	        long t = into.getId();
363	        String toSheet = into.getSheetId();
364	        if (jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND version = ?", t,
365	                into.getVersion()) == 0) {
366	            return false;
367	        }
368	        jdbc.update("UPDATE person_alias SET sheet_id = ?, person_id = ? WHERE person_id = ?", toSheet, t, f);
369	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", toSheet, t,
370	                from.getName());
371	        moveClaims(from, toSheet, t, numbers);
372	        carryStatements(f, toSheet, t);
373	        dropRest(f);
374	        return true;
375	    }
376	    /** Move the person's claims to the other sheet's person {@code t}, as {@link #transfer} describes. */
377	    private void moveClaims(Person from, String toSheet, long t, Map<Long, String> numbers) {
378	        long f = from.getId();
379	        List<Map<String, Object>> claims = jdbc.queryForList(
380	                "SELECT id, claim_number, corrects, split_from, tags FROM claim WHERE person_id = ? ORDER BY listed", f);
381	        Map<String, String> renumbered = new java.util.HashMap<>();
382	        for (Map<String, Object> claim : claims) {
383	            if (claim.get("claim_number") != null) {
384	                renumbered.put((String) claim.get("claim_number"), numbers.get(((Number) claim.get("id")).longValue()));
385	            }
386	        }
387	        for (Map<String, Object> claim : claims) {
388	            long id = ((Number) claim.get("id")).longValue();
389	            Long listed = jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE "
390	                    + "(UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)", Long.class, toSheet);
391	            jdbc.update("UPDATE claim SET sheet_id = ?, person_id = ?, listed = ?, claim_number = ?, corrects = ?,"
392	                    + " split_from = ?, ref = NULL, settle_batch = NULL WHERE id = ?",
393	                    toSheet, t, listed, numbers.get(id), renumbered.get((String) claim.get("corrects")),
394	                    renumbered.get((String) claim.get("split_from")), id);
395	            jdbc.update("UPDATE claim_log SET sheet_id = ? WHERE claim_id = ?", toSheet, id);
396	            jdbc.update("UPDATE claim_comment SET sheet_id = ? WHERE claim_id = ?", toSheet, id);
397	            jdbc.update("UPDATE claim_line SET sheet_id = ? WHERE claim_id = ?", toSheet, id);
398	            jdbc.update("DELETE FROM claim_lock WHERE claim_id = ?", id);
399	            String tags = (String) claim.get("tags");
400	            if (tags != null) {
401	                for (String tag : tags.split(",")) {
402	                    jdbc.update("MERGE INTO claim_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", toSheet, tag);
403	                }
404	            }
405	        }
406	    }
407	    /**
408	     * Carry person {@code f}'s statements to person {@code t} on {@code toSheet}: {@code t}'s count becomes their own
409	     * plus {@code f}'s, and {@code t}'s last statement stays theirs (or, having none, becomes {@code f}'s). The last
410	     * statement is the one with the highest id, so {@code t}'s own are taken again after {@code f}'s, in their order.
411	     */
412	    private void carryStatements(long f, String toSheet, long t) {
413	        List<Long> own = jdbc.queryForList("SELECT id FROM statement WHERE person_id = ? ORDER BY id", Long.class, t);
414	        jdbc.update("UPDATE statement SET sheet_id = ?, person_id = ? WHERE person_id = ?", toSheet, t, f);
415	        for (Long id : own) {
416	            jdbc.update("INSERT INTO statement (sheet_id, person_id, due_total, taken_on)"
417	                    + " SELECT sheet_id, person_id, due_total, taken_on FROM statement WHERE id = ?", id);
418	            jdbc.update("DELETE FROM statement WHERE id = ?", id);
419	        }
420	    }
421	    /** Drop everything else of the person's here, and the person. */
422	    private void dropRest(long f) {
423	        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", f, f);
424	        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", f);
425	        jdbc.update("DELETE FROM plan_claim WHERE plan_id IN (SELECT id FROM plan WHERE person_id = ?)", f);
426	        jdbc.update("DELETE FROM plan WHERE person_id = ?", f);
427	        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", f);
428	        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", f);
429	        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", f);
430	        jdbc.update("DELETE FROM statement WHERE person_id = ?", f);
431	        jdbc.update("DELETE FROM person_snapshot WHERE person_id = ?", f);
432	        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", f);
433	        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", f);
434	        jdbc.update("DELETE FROM person WHERE id = ?", f);
435	    }
436	    /** Sets each person's patrons' names, in the order named, their grades, their holds and their past retirements. */
437	    private List<Person> withPatrons(String sheetId, List<Person> people) {
438	        if (people.isEmpty()) {
439	            return people;
440	        }
441	        Map<Long, List<GradeFrom>> grades = jdbc.query(
442	                "SELECT g.person_id, g.grade, g.from_date FROM person_grade g JOIN person q ON q.id = g.person_id"
443	                        + " WHERE q.sheet_id = ?",
444	                (rs, n) -> Map.entry(rs.getLong("person_id"), GRADE.mapRow(rs, n)), sheetId).stream()
445	                .collect(Collectors.groupingBy(Map.Entry::getKey,
446	                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
447	        for (Person person : people) {
448	            person.setGrades(grades.getOrDefault(person.getId(), List.of()));
449	        }
450	        Map<Long, List<HoldSpan>> holds = jdbc.query(
451	                "SELECT h.person_id, h.from_date, h.to_date FROM person_hold h JOIN person q ON q.id = h.person_id"
452	                        + " WHERE q.sheet_id = ? ORDER BY h.id",
453	                (rs, n) -> Map.entry(rs.getLong("person_id"), new HoldSpan(rs.getObject("from_date", LocalDate.class),
454	                        rs.getObject("to_date", LocalDate.class))), sheetId).stream()
455	                .collect(Collectors.groupingBy(Map.Entry::getKey,
456	                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
457	        for (Person person : people) {
458	            person.setHolds(holds.getOrDefault(person.getId(), List.of()));
459	        }
460	        Map<Long, List<RetirementSpan>> retirements = jdbc.query(
461	                "SELECT r.person_id, r.from_date, r.to_date FROM person_retirement r JOIN person q ON q.id = r.person_id"
462	                        + " WHERE q.sheet_id = ? ORDER BY r.id",
463	                (rs, n) -> Map.entry(rs.getLong("person_id"), new RetirementSpan(
464	                        rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class))), sheetId)
465	                .stream().collect(Collectors.groupingBy(Map.Entry::getKey,
466	                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
467	        for (Person person : people) {
468	            person.setRetirements(retirements.getOrDefault(person.getId(), List.of()));
469	        }
470	        Map<Long, List<String>> patrons = jdbc.query(
471	                "SELECT pp.person_id, q.name FROM person_patron pp JOIN person q ON q.id = pp.patron_id"
472	                        + " WHERE q.sheet_id = ? ORDER BY pp.named",
473	                (rs, n) -> Map.entry(rs.getLong("person_id"), rs.getString("name")), sheetId).stream()
474	                .collect(Collectors.groupingBy(Map.Entry::getKey,
475	                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
476	        for (Person person : people) {
477	            person.setPatrons(patrons.getOrDefault(person.getId(), List.of()));
478	        }
479	        Map<Long, List<String>> aliases = jdbc.query(
480	                "SELECT a.person_id, a.alias FROM person_alias a WHERE a.sheet_id = ?",
481	                (rs, n) -> Map.entry(rs.getLong("person_id"), rs.getString("alias")), sheetId).stream()
482	                .collect(Collectors.groupingBy(Map.Entry::getKey,
483	                        Collectors.mapping(Map.Entry::getValue, Collectors.toList())));
484	        for (Person person : people) {
