644	/**
645	 * Takes the person's statement on the sheet's today: records their due-total, binds each of their counting claims
646	 * to the figure it has now, and unbinds the rest. A claim's figure is its settled due when it has one, else the
647	 * figure its last statement bound it to, else its amount times the rate in force on the claim's date of its
648	 * person's grade in force on that date (rounded as the claim rounds by the sheet's policy date; none without a rate) — the rate figure, never floored. The due-total is the counting claims' dues
649	 * added up: each figure with its late charge on top while it is overdue, then at least the floor in force on the claim's date (neither is bound); n/a
650	 * (null) when the grade has no rate today and no counting claim keeps a settled or bound figure; at most the sheet's cap in force on its today.
651	 * <p>
652	 * Taken as of a date on or before the sheet's today, the statement reads the sheet as it stood at the end of that
653	 * date (every change made while the sheet's today was that date or earlier, none made later; see SheetHistory), that
654	 * date standing in for the sheet's today in every figure: the claims of theirs that counted then are bound to their
655	 * figures then, every other claim of theirs is unbound, and the statement is dated that date. A date after the
656	 * sheet's today is refused, as is one before the person was on the sheet.
657	 */
658	public class TakeStatement {
659	    public void take(@Val Person person, @Val StatementAsOf asOf, ClaimRepository claims, RateRepository rates,
660	            SheetRepository sheets, SettingRepository settings, StatementRepository statements, SheetHistory history,
661	            Out<Statement> taken) throws BadRequestException {
662	        String sheetId = person.getSheetId();
663	        LocalDate today = sheets.today(sheetId);
664	        LocalDate on = asOf.on() == null ? today : asOf.on();
665	        if (on.isAfter(today)) {
666	            throw new BadRequestException("A statement cannot be taken as of a date after the sheet's today (" + today + ")");
667	        }
668	        Figures figures;
669	        if (on.equals(today)) {
670	            figures = figures(person, claims, rates, settings, today);
671	        } else {
672	            Long snapshot = history.snapshotAsOf(sheetId, on);
673	            figures = snapshot == null ? null : history.read(sheetId, snapshot, on, jdbc -> {
674	                Person then = new PersonRepository(jdbc).find(sheetId, person.getId());
675	                return then == null ? null
676	                        : figures(then, new ClaimRepository(jdbc), new RateRepository(jdbc), new SettingRepository(jdbc), on);
677	            });
678	            if (figures == null) {
679	                throw new BadRequestException(person.getName() + " was not on the sheet on " + on);
680	            }
681	        }
682	        for (Claim c : claims.listOf(sheetId, person.getId())) {
683	            boolean counted = figures.bound().containsKey(c.getId());
684	            claims.bind(c.getId(), counted, counted ? figures.bound().get(c.getId()) : null);
685	        }
686	        statements.insert(sheetId, person.getId(), figures.dueTotal(), on);
687	        person.setStatements(new Statements(person.getStatements().count() + 1, figures.dueTotal(), on));
688	        taken.set(new Statement(figures.dueTotal(), figures.bound().size(), asOf.on()));
689	    }
690	    /** A statement's figures: its due-total (null: n/a) and the figure each counting claim is bound to (null: n/a), by id. */
691	    private record Figures(BigDecimal dueTotal, Map<Long, BigDecimal> bound) {
692	    }
693	    /** The person's statement figures as of {@code today}, read through the repositories given. */
694	    private static Figures figures(Person person, ClaimRepository claims, RateRepository rates,
695	            SettingRepository settings, LocalDate today) {
696	        String sheetId = person.getSheetId();
697	        LateCharge late = settings.lateCharge(sheetId, today);
698	        List<Claim> mine = claims.listOf(sheetId, person.getId());
699	        Map<Long, BigDecimal> bound = new HashMap<>();
700	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
701	        boolean kept = false;
702	        for (Claim c : mine) {
703	            // OPEN and PENDING claims dated within a hold, or once the retirement date is reached, do not count, unless the last statement bound them; a claim
704	            // deferred past today does not count and is left unbound.
705	            if (!c.getStatus().counts() || Rollup.held(c, person, today) || c.isDeferredOn(today)) {
706	                continue;
707	            }
708	            kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
709	            BigDecimal figure = figure(c, person, rates, late);
710	            // A figure at a grade other than today's does not hang on today's grade having a rate; nor does one
711	            // dated on or before today, whose rate may have ended since.
712	            kept |= figure != null && (!person.gradeOn(c.getDate()).equals(person.getGrade()) || !c.getDate().isAfter(today));
713	            if (figure != null) {
714	                sum = sum.add(late.due(c, figure));
715	            }
716	            bound.put(c.getId(), figure);
717	        }
718	        BigDecimal dueTotal = SettingRepository.capped(
