36	/**
37	 * Clones the sheet to another sheet id: only a steward may, and only to a sheet never used (not stored). See
38	 * {@link SheetCloneRepository} for what is copied. Each claim that had a number takes the clone's next one, in the
39	 * order the originals were opened (by the sheet's today when each was opened, then by the order they are added to the
40	 * clone: by person in list order, then by claim).
41	 */
42	public class CloneSheet {
43	    public void clone(@Val SheetResponse sheet, @Val CloneInput input, @Val ChangedBy by, RoleRepository roles,
44	            SheetRepository sheets, SheetCloneRepository cloner, PersonRepository people, ClaimRepository claims,
45	            ClaimLogRepository log, SettingRepository settings, PeriodRepository periods, Rollup rollup,
46	            Out<RollupBefore> before) throws BadRequestException {
47	        String from = sheet.id();
48	        String to = input.to();
49	        if (!Role.STEWARD.equals(roles.roleOf(from, by.name()))) {
50	            throw new BadRequestException("Only a steward may clone the sheet");
51	        }
52	        if (to.equals(from) || sheets.exists(to)) {
53	            throw new BadRequestException("That sheet is already in use: clone to a sheet never used");
54	        }
55	        before.set(new RollupBefore(rollup.snapshot(to)));
56	        Map<Long, Long> personIds = cloner.copySheet(from, to);
57	        List<Claim> ordered = new ArrayList<>();
58	        List<Claim> all = claims.list(from);
59	        for (Person person : people.list(from)) {
60	            all.stream().filter(c -> c.getPersonId() == person.getId())
61	                    .sorted(Comparator.comparingLong(Claim::getId)).forEach(ordered::add);
62	        }
63	        Map<Long, LocalDate> opened = new HashMap<>();
64	        for (Claim claim : ordered) {
65	            if (claim.getNumber() != null) {
66	                LocalDate on = log.firstOn(from, claim.getId(), ClaimStatus.OPEN);
67	                opened.put(claim.getId(), on != null ? on : claim.getDate());
68	            }
69	        }
70	        Map<Long, String> numbers = new LinkedHashMap<>();
71	        ordered.stream().filter(c -> opened.containsKey(c.getId()))
72	                .sorted(Comparator.comparing(c -> opened.get(c.getId())))
73	                .forEach(c -> numbers.put(c.getId(),
74	                        ClaimNumbering.number(to, c.getDueBy(), claims, settings, sheets, periods)));
75	        cloner.copyClaims(from, to, personIds, numbers);
76	    }
77	}
