395	/**
396	 * A sheet as it stood at the end of a date. As the sheet's today moves on, the sheet is snapshotted (schema hist): the
397	 * snapshot holds every change made while its today was the old one or earlier, and none made later. Read as of a date,
398	 * the latest snapshot taken as the today moved on from that date or before it to a later one is laid out as the live
399	 * tables (schema asof), its today standing at that date, and read by the app's own repositories.
400	 */
401	@Repository
402	public class SheetHistory {
403	    /** The tables the screen reads (a statement's figures among them), parents before children. */
404	    private static final List<String> TABLES = List.of("sheet", "person", "person_grade", "person_hold", "person_retirement",
405	            "person_patron", "person_alias", "person_snapshot", "person_watch", "statement", "claim", "claim_log", "claim_lock", "rate", "sheet_setting",
406	            "sheet_setting_from", "period", "period_person_total", "sheet_role", "sheet_delegation", "holiday", "claim_tag", "void_reason", "claim_comment", "claim_line", "claim_template",
407	            "pool", "pool_member", "plan", "plan_claim");
408	    private final JdbcTemplate jdbc;
409	    private final DataSource dataSource;
410	    public SheetHistory(JdbcTemplate jdbc, DataSource dataSource) {
411	        this.jdbc = jdbc;
412	        this.dataSource = dataSource;
413	    }
414	    /** Snapshot the sheet as its today moves on from {@code through} to the later {@code until}. */
415	    public long snapshot(String sheetId, LocalDate through, LocalDate until) {
416	        long id = jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO sheet_snapshot (sheet_id, through, until)"
417	                + " VALUES (?, ?, ?))", Long.class, sheetId, Date.valueOf(through), Date.valueOf(until));
418	        for (String table : TABLES) {
419	            String columns = columns(jdbc, table);
420	            jdbc.update("INSERT INTO hist." + table + " (" + columns + ", snapshot_id) SELECT " + columns + ", ? FROM "
421	                    + "public." + table + " WHERE " + ofSheet(table, "public"), id, sheetId);
422	        }
423	        return id;
424	    }
425	    /** Lay the period, as it now stands live (closed, its totals), over the snapshot: a period closed as the today
426	     *  moved on counts as closed by the end of the old today. */
427	    public void refreshPeriod(long snapshotId, long periodId) {
428	        for (String table : List.of("period_person_total", "period")) {
429	            String key = table.equals("period") ? "id" : "period_id";
430	            jdbc.update("DELETE FROM hist." + table + " WHERE snapshot_id = ? AND " + key + " = ?", snapshotId, periodId);
431	        }
432	        for (String table : List.of("period", "period_person_total")) {
433	            String key = table.equals("period") ? "id" : "period_id";
434	            String columns = columns(jdbc, table);
435	            jdbc.update("INSERT INTO hist." + table + " (" + columns + ", snapshot_id) SELECT " + columns + ", ? FROM "
436	                    + "public." + table + " WHERE " + key + " = ?", snapshotId, periodId);
437	        }
438	    }
439	    /** The snapshot holding the sheet as it stood at the end of the date; null when its today never moved on past it. */
440	    public Long snapshotAsOf(String sheetId, LocalDate on) {
441	        return jdbc.query("SELECT id FROM sheet_snapshot WHERE sheet_id = ? AND through <= ? AND until > ?"
442	                + " ORDER BY id DESC LIMIT 1", (rs, n) -> rs.getLong(1), sheetId, Date.valueOf(on), Date.valueOf(on))
443	                .stream().findFirst().orElse(null);
444	    }
445	    /**
446	     * Read the snapshot, its today standing at {@code on}: {@code reader} is given a JdbcTemplate over the snapshot laid
447	     * out as the live tables, for the app's repositories to read it as they read the live sheet.
448	     */
449	    public <T> T read(String sheetId, long snapshotId, LocalDate on, Function<JdbcTemplate, T> reader) {
450	        Connection con = DataSourceUtils.getConnection(dataSource);
451	        try {
452	            JdbcTemplate asOf = new JdbcTemplate(new SingleConnectionDataSource(con, true));
453	            for (String table : TABLES) {
454	                String columns = columns(asOf, table);
455	                asOf.update("INSERT INTO asof." + table + " (" + columns + ") SELECT " + columns + " FROM hist." + table
456	                        + " WHERE snapshot_id = ?", snapshotId);
457	            }
458	            asOf.update("UPDATE asof.sheet SET today = ? WHERE id = ?", Date.valueOf(on), sheetId);
459	            asOf.execute("SET SCHEMA asof");
460	            try {
461	                return reader.apply(asOf);
462	            } finally {
463	                asOf.execute("SET SCHEMA public");
464	                for (int i = TABLES.size() - 1; i >= 0; i--) {
465	                    String table = TABLES.get(i);
466	                    asOf.update("DELETE FROM asof." + table + " WHERE " + ofSheet(table, "asof"), sheetId);
467	                }
468	            }
469	        } finally {
470	            DataSourceUtils.releaseConnection(con, dataSource);
471	        }
472	    }
473	    /**
474	     * Read the sheet as the signed-in user's screen shows it: live when {@code on} is null, else as it stood at the end
475	     * of that date, the date standing in for the sheet's today. {@code reader} is given a JdbcTemplate over the sheet
476	     * laid out as the live tables (schema asof), for the app's repositories to read it as they read the live sheet. A
477	     * date on or after the sheet's today reads every change made; a date before the earliest snapshot reads none.
478	     * The layout is rolled back once read (to a savepoint inside the request's transaction), so no other request sees it.
479	     */
480	    public <T> T view(String sheetId, LocalDate on, Function<JdbcTemplate, T> reader) {
481	        if (on == null) {
482	            return reader.apply(jdbc);
483	        }
484	        LocalDate today = jdbc.query("SELECT today FROM sheet WHERE id = ?",
485	                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, sheetId);
486	        Long snapshot = today == null || !on.isBefore(today) ? null : snapshotAsOf(sheetId, on);
487	        Connection con = DataSourceUtils.getConnection(dataSource);
488	        try {
489	            boolean autoCommit = con.getAutoCommit();
490	            String schema = con.getSchema();
491	            Savepoint before = autoCommit ? null : con.setSavepoint();
492	            con.setAutoCommit(false);
493	            try {
494	                JdbcTemplate asOf = new JdbcTemplate(new SingleConnectionDataSource(con, true));
495	                for (String table : TABLES) {
496	                    String columns = columns(asOf, table);
497	                    if (snapshot != null) {
498	                        asOf.update("INSERT INTO asof." + table + " (" + columns + ") SELECT " + columns + " FROM hist."
499	                                + table + " WHERE snapshot_id = ?", snapshot);
500	                    } else if (today != null && (!on.isBefore(today) || table.equals("sheet"))) {
501	                        // On or after its today: every change counts. Before its earliest snapshot: none does.
502	                        asOf.update("INSERT INTO asof." + table + " (" + columns + ") SELECT " + columns + " FROM public."
503	                                + table + " WHERE " + ofSheet(table, "public"), sheetId);
504	                    }
505	                }
506	                if (snapshot == null && today != null && on.isBefore(today)) {
507	                    asOf.update("UPDATE asof.sheet SET archived = FALSE, last_settle_batch = 0 WHERE id = ?", sheetId);
508	                }
509	                asOf.update("UPDATE asof.sheet SET today = ? WHERE id = ?", Date.valueOf(on), sheetId);
510	                con.setSchema("ASOF");
511	                return reader.apply(asOf);
512	            } finally {
513	                con.setSchema(schema);
514	                if (before == null) {
515	                    con.rollback();
516	                    con.setAutoCommit(true);
517	                } else {
518	                    con.rollback(before);
519	                }
520	            }
521	        } catch (SQLException e) {
522	            throw new IllegalStateException("Cannot read the sheet as of " + on, e);
523	        } finally {
524	            DataSourceUtils.releaseConnection(con, dataSource);
525	        }
526	    }
527	    /** The table's columns, as the live table lists them. */
528	    private static String columns(JdbcTemplate jdbc, String table) {
529	        return String.join(", ", jdbc.queryForList("SELECT column_name FROM information_schema.columns"
530	                + " WHERE table_schema = 'PUBLIC' AND table_name = ? ORDER BY ordinal_position", String.class,
531	                table.toUpperCase()));
532	    }
533	    /** The condition picking the sheet's rows of the table in the schema (the sheet id its one parameter). */
534	    private static String ofSheet(String table, String schema) {
535	        return switch (table) {
536	            case "sheet" -> "id = ?";
537	            case "person_grade", "person_hold", "person_retirement", "person_patron", "person_watch" ->
538	                "person_id IN (SELECT id FROM " + schema + ".person WHERE sheet_id = ?)";
539	            case "period_person_total" -> "period_id IN (SELECT id FROM " + schema + ".period WHERE sheet_id = ?)";
540	            default -> "sheet_id = ?";
541	        };
542	    }
543	}
